import { XhCheckbox } from "@xihan-ui/vue";

// 后端收的是两个状态码，界面上只有勾与不勾
const status = ref<"enabled" | "disabled">("enabled");
const enabled = computed({
  get: () => status.value === "enabled",
  set: (next) => (status.value = next ? "enabled" : "disabled"),
});

